-- Fail closed for monetary analytics when transaction currency differs from company currency.
CREATE OR REPLACE FUNCTION public.get_profitability_snapshot(p_as_of date DEFAULT CURRENT_DATE)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path TO 'public' AS $$
DECLARE v_company_id uuid:=public.current_company_id(); v_currency text; v_result jsonb;
BEGIN
 IF v_company_id IS NULL THEN RAISE EXCEPTION 'TENANT_CONTEXT_REQUIRED'; END IF;
 SELECT c.currency INTO v_currency FROM public.companies c WHERE c.id=v_company_id;
 WITH sales_base AS (SELECT s.id,s.subtotal,s.total,s.paid_amount,s.currency FROM public.sales_invoices s WHERE s.company_id=v_company_id AND s.status IS NOT NULL AND s.status NOT IN ('cancelled','void') AND s.invoice_date<=p_as_of),
 items AS (SELECT si.invoice_id,si.quantity,si.cost_price,si.line_total FROM public.sale_items si JOIN sales_base s ON s.id=si.invoice_id),
 quality AS (SELECT count(*) FILTER(WHERE subtotal IS NULL OR total IS NULL OR paid_amount IS NULL) bad_invoice_rows,(SELECT count(*) FROM items WHERE quantity IS NULL OR cost_price IS NULL OR line_total IS NULL) bad_sale_item_rows,(SELECT count(*) FROM sales_base WHERE currency IS NOT NULL AND v_currency IS NOT NULL AND currency<>v_currency) currency_mismatch_rows FROM sales_base),
 totals AS (SELECT coalesce(sum(s.subtotal) FILTER(WHERE s.subtotal IS NOT NULL),0)::numeric revenue,coalesce((SELECT sum(i.quantity*i.cost_price) FROM items i WHERE i.quantity IS NOT NULL AND i.cost_price IS NOT NULL),0)::numeric cost,count(*)::integer invoice_count FROM sales_base s)
 SELECT jsonb_build_object('status',CASE WHEN q.bad_invoice_rows=0 AND q.bad_sale_item_rows=0 AND q.currency_mismatch_rows=0 AND t.invoice_count>0 THEN 'CALCULATED' ELSE 'INSUFFICIENT_DATA' END,'currency',v_currency,'currency_status',CASE WHEN q.currency_mismatch_rows=0 AND v_currency IS NOT NULL THEN 'CONSISTENT' ELSE 'INSUFFICIENT_DATA' END,'revenue',CASE WHEN q.bad_invoice_rows=0 AND q.currency_mismatch_rows=0 THEN t.revenue END,'cost',CASE WHEN q.bad_sale_item_rows=0 AND q.currency_mismatch_rows=0 THEN t.cost END,'gross_profit',CASE WHEN q.bad_invoice_rows=0 AND q.bad_sale_item_rows=0 AND q.currency_mismatch_rows=0 THEN t.revenue-t.cost END,'gross_margin',CASE WHEN q.bad_invoice_rows=0 AND q.bad_sale_item_rows=0 AND q.currency_mismatch_rows=0 AND t.revenue<>0 THEN ((t.revenue-t.cost)/t.revenue)*100 END,'invoice_count',t.invoice_count,'bad_invoice_rows',q.bad_invoice_rows,'bad_sale_item_rows',q.bad_sale_item_rows,'currency_mismatch_rows',q.currency_mismatch_rows,'reasons',CASE WHEN q.bad_invoice_rows>0 OR q.bad_sale_item_rows>0 OR q.currency_mismatch_rows>0 OR t.invoice_count=0 THEN to_jsonb(array_remove(array[case when q.bad_invoice_rows>0 then 'INVOICE_DATA_QUALITY' end,case when q.bad_sale_item_rows>0 then 'SALE_ITEM_DATA_QUALITY' end,case when q.currency_mismatch_rows>0 then 'CURRENCY_MISMATCH' end,case when t.invoice_count=0 then 'NO_SALES_DATA' end],null)) ELSE '[]'::jsonb END,'as_of',p_as_of) INTO v_result FROM quality q CROSS JOIN totals t;
 RETURN v_result;
END; $$;

CREATE OR REPLACE FUNCTION public.get_purchase_summary(p_company_id uuid,p_from date DEFAULT NULL,p_to date DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path TO 'public' AS $$
DECLARE v_company_id uuid:=public.current_company_id(); v_currency text; v_result jsonb; v_mismatch bigint;
BEGIN
 IF v_company_id IS NULL THEN RAISE EXCEPTION 'TENANT_CONTEXT_REQUIRED'; END IF;
 IF p_company_id IS DISTINCT FROM v_company_id THEN RAISE EXCEPTION 'TENANT_CONTEXT_MISMATCH'; END IF;
 IF p_from IS NOT NULL AND p_to IS NOT NULL AND p_from>p_to THEN RAISE EXCEPTION 'REPORT_DATE_RANGE_INVALID'; END IF;
 SELECT c.currency INTO v_currency FROM public.companies c WHERE c.id=v_company_id;
 SELECT count(*) FILTER(WHERE pi.currency IS NOT NULL AND v_currency IS NOT NULL AND pi.currency<>v_currency) INTO v_mismatch FROM public.purchase_invoices pi WHERE pi.company_id=v_company_id AND pi.status NOT IN ('cancelled','void') AND (p_from IS NULL OR pi.invoice_date>=p_from) AND (p_to IS NULL OR pi.invoice_date<=p_to);
 SELECT jsonb_build_object('total',CASE WHEN v_mismatch=0 THEN coalesce(sum(pi.total),0) END,'count',count(*)::integer,'supplier_count',count(distinct pi.supplier_id)::integer,'average',CASE WHEN v_mismatch=0 AND count(*)>0 THEN sum(pi.total)/count(*) END,'as_of',coalesce(p_to,current_date),'data_status',CASE WHEN count(*)=0 THEN 'NO_DATA' WHEN v_mismatch>0 THEN 'INSUFFICIENT_DATA' ELSE 'CALCULATED' END,'currency',v_currency,'currency_status',CASE WHEN v_mismatch=0 AND v_currency IS NOT NULL THEN 'CONSISTENT' ELSE 'INSUFFICIENT_DATA' END,'currency_mismatch_rows',v_mismatch) INTO v_result FROM public.purchase_invoices pi WHERE pi.company_id=v_company_id AND pi.status NOT IN ('cancelled','void') AND (p_from IS NULL OR pi.invoice_date>=p_from) AND (p_to IS NULL OR pi.invoice_date<=p_to);
 RETURN v_result;
END; $$;

CREATE OR REPLACE FUNCTION public.get_sales_secondary_metrics(p_company_id uuid,p_months integer DEFAULT 6,p_limit integer DEFAULT 5,p_from date DEFAULT NULL,p_to date DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path TO 'public' AS $$
DECLARE v_company_id uuid:=public.current_company_id(); v_currency text; v_mismatch bigint; v_as_of date:=coalesce(p_to,current_date); v_months integer:=greatest(1,least(coalesce(p_months,6),24)); v_limit integer:=greatest(1,least(coalesce(p_limit,5),100)); v_result jsonb;
BEGIN
 IF v_company_id IS NULL THEN RAISE EXCEPTION 'TENANT_CONTEXT_REQUIRED'; END IF;
 IF p_company_id IS DISTINCT FROM v_company_id THEN RAISE EXCEPTION 'TENANT_CONTEXT_MISMATCH'; END IF;
 IF p_from IS NOT NULL AND p_to IS NOT NULL AND p_from>p_to THEN RAISE EXCEPTION 'REPORT_DATE_RANGE_INVALID'; END IF;
 SELECT c.currency INTO v_currency FROM public.companies c WHERE c.id=v_company_id;
 SELECT count(*) FILTER(WHERE s.currency IS NOT NULL AND v_currency IS NOT NULL AND s.currency<>v_currency) INTO v_mismatch FROM public.sales_invoices s WHERE s.company_id=v_company_id AND s.status NOT IN ('cancelled','void') AND (p_from IS NULL OR s.invoice_date>=p_from) AND (p_to IS NULL OR s.invoice_date<=p_to);
 IF v_mismatch>0 THEN RETURN jsonb_build_object('as_of',v_as_of,'months',v_months,'limit',v_limit,'monthly_trend','[]'::jsonb,'top_customers','[]'::jsonb,'top_products','[]'::jsonb,'category_breakdown','[]'::jsonb,'aging_buckets','[]'::jsonb,'status','INSUFFICIENT_DATA','currency',v_currency,'currency_status','INSUFFICIENT_DATA','currency_mismatch_rows',v_mismatch); END IF;
 WITH filtered_invoices AS (SELECT s.id,s.customer_id,s.subtotal,s.total,s.paid_amount,s.due_date,s.invoice_date FROM public.sales_invoices s WHERE s.company_id=v_company_id AND s.status NOT IN ('cancelled','void') AND (p_from IS NULL OR s.invoice_date>=p_from) AND (p_to IS NULL OR s.invoice_date<=p_to)), filtered_items AS (SELECT si.invoice_id,si.product_id,si.quantity,si.line_total,si.cost_price,p.name product_name,c.name category_name FROM public.sale_items si JOIN filtered_invoices fi ON fi.id=si.invoice_id LEFT JOIN public.products p ON p.id=si.product_id AND p.company_id=v_company_id LEFT JOIN public.categories c ON c.id=p.category_id AND c.company_id=v_company_id), monthly AS (SELECT jsonb_agg(jsonb_build_object('month',to_char(m.month_start,'YYYY-MM'),'sales',coalesce(x.sales,0),'cost',coalesce(x.cost,0),'profit',coalesce(x.sales,0)-coalesce(x.cost,0),'invoices',coalesce(x.invoices,0)) order by m.month_start) value FROM generate_series(date_trunc('month',v_as_of)::date-((v_months-1)*interval '1 month'),date_trunc('month',v_as_of)::date,interval '1 month') m(month_start) LEFT JOIN (SELECT date_trunc('month',fi.invoice_date)::date month_start,sum(fi.subtotal) sales,sum(coalesce(fi_cost.cost,0)) cost,count(*)::integer invoices FROM filtered_invoices fi LEFT JOIN (SELECT invoice_id,sum(quantity*cost_price) cost FROM filtered_items WHERE cost_price IS NOT NULL AND quantity IS NOT NULL GROUP BY invoice_id) fi_cost ON fi_cost.invoice_id=fi.id GROUP BY date_trunc('month',fi.invoice_date)::date) x ON x.month_start=m.month_start), top_customers AS (SELECT coalesce(jsonb_agg(jsonb_build_object('id',q.customer_id,'name',q.name,'value',q.value) order by q.value desc),'[]'::jsonb) value FROM (SELECT fi.customer_id,coalesce(c.name,fi.customer_id::text) name,sum(fi.subtotal) value FROM filtered_invoices fi LEFT JOIN public.customers c ON c.id=fi.customer_id AND c.company_id=v_company_id GROUP BY fi.customer_id,c.name ORDER BY value desc LIMIT v_limit) q), top_products AS (SELECT coalesce(jsonb_agg(jsonb_build_object('id',q.product_id,'name',q.name,'value',q.value,'secondary',q.quantity) order by q.value desc),'[]'::jsonb) value FROM (SELECT fi.product_id,coalesce(fi.product_name,fi.product_id::text) name,sum(fi.line_total) value,sum(fi.quantity) quantity FROM filtered_items fi WHERE fi.product_id IS NOT NULL GROUP BY fi.product_id,fi.product_name ORDER BY value desc LIMIT v_limit) q), categories AS (SELECT coalesce(jsonb_agg(jsonb_build_object('name',q.name,'sales',q.sales,'profit',case when q.missing_cost>0 then null else q.sales-q.cost end,'quantity',q.quantity,'data_status',case when q.missing_cost>0 then 'INSUFFICIENT_DATA' else 'CALCULATED' end) order by q.sales desc),'[]'::jsonb) value FROM (SELECT coalesce(fi.category_name,'غير مصنف') name,sum(fi.line_total) sales,sum(case when fi.cost_price is null or fi.quantity is null then 0 else fi.quantity*fi.cost_price end) cost,sum(fi.quantity) quantity,count(*) filter(where fi.cost_price is null or fi.quantity is null) missing_cost FROM filtered_items fi GROUP BY coalesce(fi.category_name,'غير مصنف')) q), aging_rows AS (SELECT case when fi.due_date is null then 'UNDATED' when greatest(0,v_as_of-fi.due_date)<=30 then '0-30' when greatest(0,v_as_of-fi.due_date)<=60 then '31-60' when greatest(0,v_as_of-fi.due_date)<=90 then '61-90' else '90+' end bucket,case when fi.due_date is null then 5 when greatest(0,v_as_of-fi.due_date)<=30 then 1 when greatest(0,v_as_of-fi.due_date)<=60 then 2 when greatest(0,v_as_of-fi.due_date)<=90 then 3 else 4 end bucket_order,greatest(fi.total-fi.paid_amount,0) outstanding FROM filtered_invoices fi WHERE greatest(fi.total-fi.paid_amount,0)>0), aging AS (SELECT coalesce(jsonb_agg(jsonb_build_object('bucket',q.bucket,'amount',q.amount,'count',q.count) order by q.bucket_order),'[]'::jsonb) value FROM (SELECT bucket,bucket_order,sum(outstanding) amount,count(*)::integer count FROM aging_rows GROUP BY bucket,bucket_order) q) SELECT jsonb_build_object('as_of',v_as_of,'months',v_months,'limit',v_limit,'monthly_trend',coalesce(monthly.value,'[]'::jsonb),'top_customers',top_customers.value,'top_products',top_products.value,'category_breakdown',categories.value,'aging_buckets',aging.value,'status','CALCULATED','currency',v_currency,'currency_status','CONSISTENT','currency_mismatch_rows',0) INTO v_result FROM monthly,top_customers,top_products,categories,aging;
 RETURN v_result;
END; $$;

CREATE OR REPLACE FUNCTION public.get_rfm_snapshot(p_as_of date DEFAULT CURRENT_DATE,p_limit integer DEFAULT 500)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path TO 'public' AS $$
DECLARE v_company_id uuid:=public.current_company_id(); v_currency text; v_mismatch bigint; v_limit integer:=least(greatest(coalesce(p_limit,500),1),500); v_unknown bigint; v_rows jsonb; v_status text;
BEGIN
 IF v_company_id IS NULL THEN RAISE EXCEPTION 'TENANT_CONTEXT_REQUIRED'; END IF;
 SELECT c.currency INTO v_currency FROM public.companies c WHERE c.id=v_company_id;
 SELECT count(*) FILTER(WHERE si.currency IS NOT NULL AND v_currency IS NOT NULL AND si.currency<>v_currency) INTO v_mismatch FROM public.sales_invoices si WHERE si.company_id=v_company_id AND si.status NOT IN ('cancelled','void');
 IF v_mismatch>0 THEN RETURN jsonb_build_object('asOf',p_as_of,'rows','[]'::jsonb,'unknownRows',0,'status','INSUFFICIENT_DATA','currency',v_currency,'currency_status','INSUFFICIENT_DATA','currency_mismatch_rows',v_mismatch); END IF;
 WITH raw AS (SELECT si.customer_id,c.name customer_name,si.invoice_date,si.total FROM public.sales_invoices si LEFT JOIN public.customers c ON c.id=si.customer_id AND c.company_id=v_company_id WHERE si.company_id=v_company_id AND si.status NOT IN ('cancelled','void')), valid AS (SELECT * FROM raw WHERE customer_id IS NOT NULL AND customer_name IS NOT NULL AND invoice_date IS NOT NULL AND total IS NOT NULL), agg AS (SELECT customer_id,max(customer_name) customer_name,(p_as_of-max(invoice_date::date))::integer recency,count(*)::integer frequency,sum(total)::numeric monetary FROM valid GROUP BY customer_id), scored AS (SELECT a.*,least(5,floor((row_number() over(order by recency asc,customer_id)-1)::numeric/greatest(count(*) over(),1)*5)::integer+1) r_score,least(5,floor((row_number() over(order by frequency desc,customer_id)-1)::numeric/greatest(count(*) over(),1)*5)::integer+1) f_score,least(5,floor((row_number() over(order by monetary desc,customer_id)-1)::numeric/greatest(count(*) over(),1)*5)::integer+1) m_score FROM agg a), final_rows AS (SELECT customer_id,customer_name,recency,frequency,monetary,r_score,f_score,m_score,case when r_score+f_score+m_score>=13 then 'أبطال' when r_score+f_score+m_score>=10 then 'مخلصون' when r_score+f_score+m_score>=7 then 'واعدون' when r_score+f_score+m_score>=4 then 'معرضون للخطر' else 'خاملون' end rfm_segment FROM scored ORDER BY (r_score+f_score+m_score) DESC,monetary DESC,customer_id LIMIT v_limit) SELECT (SELECT count(*) FILTER(where customer_id IS NULL OR customer_name IS NULL OR invoice_date IS NULL OR total IS NULL) FROM raw),coalesce((SELECT jsonb_agg(to_jsonb(fr)) FROM final_rows fr),'[]'::jsonb),case when not exists(select 1 from valid) then 'INSUFFICIENT_DATA' else 'CALCULATED' end INTO v_unknown,v_rows,v_status;
 RETURN jsonb_build_object('asOf',p_as_of,'rows',v_rows,'unknownRows',v_unknown,'status',v_status,'currency',v_currency,'currency_status','CONSISTENT','currency_mismatch_rows',0);
END; $$;

CREATE OR REPLACE FUNCTION public.get_aging_snapshot(p_as_of date DEFAULT CURRENT_DATE)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path TO 'public' AS $$
DECLARE v_company_id uuid:=public.current_company_id(); v_currency text; v_mismatch bigint; v_unknown bigint; v_rows jsonb; v_status text;
BEGIN
 IF v_company_id IS NULL THEN RAISE EXCEPTION 'TENANT_CONTEXT_REQUIRED'; END IF;
 SELECT c.currency INTO v_currency FROM public.companies c WHERE c.id=v_company_id;
 SELECT count(*) FILTER(WHERE si.currency IS NOT NULL AND v_currency IS NOT NULL AND si.currency<>v_currency) INTO v_mismatch FROM public.sales_invoices si WHERE si.company_id=v_company_id AND si.status NOT IN ('cancelled','void');
 IF v_mismatch>0 THEN RETURN jsonb_build_object('asOf',p_as_of,'rows','[]'::jsonb,'unknownRows',0,'status','INSUFFICIENT_DATA','currency',v_currency,'currency_status','INSUFFICIENT_DATA','currency_mismatch_rows',v_mismatch); END IF;
 WITH raw AS (SELECT si.total,si.paid_amount,si.due_date,si.invoice_date FROM public.sales_invoices si WHERE si.company_id=v_company_id AND si.status NOT IN ('cancelled','void')), classified AS (SELECT case when due_date is null and invoice_date is null then 'UNDATED' when coalesce(due_date,invoice_date)::date>p_as_of then '0-30' when p_as_of-coalesce(due_date,invoice_date)::date<=30 then '0-30' when p_as_of-coalesce(due_date,invoice_date)::date<=60 then '31-60' when p_as_of-coalesce(due_date,invoice_date)::date<=90 then '61-90' else '90+' end bucket,case when total is null or paid_amount is null then null else total-paid_amount end outstanding,case when total is null or paid_amount is null or (due_date is null and invoice_date is null) then 1 else 0 end unknown FROM raw), agg AS (SELECT bucket,coalesce(sum(outstanding),0) amount,count(*) FILTER(where outstanding IS NOT NULL AND outstanding>0) count FROM classified WHERE outstanding IS NULL OR outstanding>0 GROUP BY bucket) SELECT (SELECT count(*) FROM classified WHERE unknown=1),coalesce((SELECT jsonb_agg(jsonb_build_object('name',bucket,'amount',amount,'count',count) ORDER BY CASE bucket WHEN '0-30' THEN 1 WHEN '31-60' THEN 2 WHEN '61-90' THEN 3 WHEN '90+' THEN 4 ELSE 5 END) FROM agg),'[]'::jsonb),case when not exists(select 1 from raw) then 'NO_DATA' when (SELECT count(*) FROM classified WHERE unknown=1)>0 then 'INSUFFICIENT_DATA' else 'CALCULATED' end INTO v_unknown,v_rows,v_status;
 RETURN jsonb_build_object('asOf',p_as_of,'rows',v_rows,'unknownRows',v_unknown,'status',v_status,'currency',v_currency,'currency_status','CONSISTENT','currency_mismatch_rows',0);
END; $$;

REVOKE ALL ON FUNCTION public.get_profitability_snapshot(date) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_purchase_summary(uuid,date,date) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_sales_secondary_metrics(uuid,integer,integer,date,date) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_rfm_snapshot(date,integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_aging_snapshot(date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_profitability_snapshot(date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_purchase_summary(uuid,date,date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_sales_secondary_metrics(uuid,integer,integer,date,date) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_rfm_snapshot(date,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_aging_snapshot(date) TO authenticated;
